const ALLOWED = ["facebook","instagram","linkedin","twitter","threads","bluesky","tiktok","youtube"];
function parsePlatforms(raw) {
  const list = (Array.isArray(raw) ? raw : String(raw || '').split(','))
    .map((p) => String(p).trim().toLowerCase())
    .filter(Boolean)
    .map((p) => (p === 'x' ? 'twitter' : p));
  const unknown = list.filter((p) => !ALLOWED.includes(p));
  if (unknown.length) throw new Error('Socialync cannot post to: ' + unknown.join(', ') + '. Use: ' + ALLOWED.join(', ') + '.');
  if (!list.length) throw new Error('Set at least one platform in the Settings node.');
  return [...new Set(list)];
}
// '2026-11-12 09:30' is read in the Settings time zone. A value with Z or an offset is used as written.
function parseWhen(text, zone) {
  const s = String(text || '').trim();
  if (!s) return null;
  if (/([zZ]|[+-]\d{2}:?\d{2})$/.test(s)) {
    const d = new Date(s);
    return isNaN(d.getTime()) ? null : d;
  }
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{2}))?/);
  if (!m) return null;
  const [y, mo, d] = m.slice(1, 4).map(Number);
  const h = m[4] === undefined ? 9 : Number(m[4]);
  const mi = m[5] === undefined ? 0 : Number(m[5]);
  const guess = Date.UTC(y, mo - 1, d, h, mi);
  const offsetAt = (t) => {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: zone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
    }).formatToParts(new Date(t));
    const v = {};
    for (const p of parts) if (p.type !== 'literal') v[p.type] = Number(p.value);
    return Date.UTC(v.year, v.month - 1, v.day, v.hour, v.minute, v.second) - t;
  };
  let utc = guess - offsetAt(guess);
  utc = guess - offsetAt(utc);
  return new Date(utc);
}
// A short hash of the content, so the key stays the same on every run for the same row.
function shortHash(text) {
  let h = 5381;
  for (let i = 0; i < text.length; i++) h = ((h * 33) ^ text.charCodeAt(i)) >>> 0;
  return h.toString(36);
}
// Socialync accepts 1 to 255 letters, digits and _ . : - in an Idempotency Key.
function safeKey(prefix, value) {
  return (prefix + ':' + String(value)).replace(/[^A-Za-z0-9_.:-]/g, '-').slice(0, 200);
}
const page = $('Get the next Ready page').first().json;
const s = $input.first().json;
const props = page.properties || {};
const problem = (message) => [{ json: { ok: false, problem: message } }];

// Reads a Notion property value as plain text, whatever its type.
function plain(p) {
  if (!p) return '';
  const join = (list) => (list || []).map((t) => t.plain_text || '').join('');
  switch (p.type) {
    case 'title': return join(p.title);
    case 'rich_text': return join(p.rich_text);
    case 'url': return p.url || '';
    case 'select': return p.select ? p.select.name : '';
    case 'status': return p.status ? p.status.name : '';
    case 'multi_select': return (p.multi_select || []).map((o) => o.name).join(',');
    case 'date': return p.date ? p.date.start : '';
    case 'files': {
      const f = (p.files || [])[0];
      return f ? (f.external ? f.external.url : f.file ? f.file.url : '') : '';
    }
    default: return '';
  }
}

try {
  const caption = plain(props.Caption).trim();
  if (!caption) return problem('Caption is empty.');
  const platforms = parsePlatforms(plain(props.Platforms).trim() || s.defaultPlatforms);
  const imageUrl = plain(props.Image).trim();
  const videoUrl = plain(props['Video URL']).trim();
  if (imageUrl && videoUrl) return problem('Fill in only one of Image and Video URL.');
  for (const link of [imageUrl, videoUrl]) {
    if (link && !/^https:\/\//i.test(link)) return problem('Image and Video URL need public https links.');
  }
  if (platforms.includes('instagram') && !imageUrl && !videoUrl) return problem('Instagram needs an Image or a Video URL.');
  const title = plain(props.Name).trim();
  if (platforms.includes('youtube') && !title) return problem('YouTube needs the page title.');
  const level = String(s.tiktokPrivacyLevel || '').trim();
  if (platforms.includes('tiktok') && !level) return problem('TikTok needs a privacy level. Set tiktokPrivacyLevel in Settings.');

  const earliest = Date.now() + Math.max(5, Number(s.publishDelayMinutes) || 60) * 60000;
  let when = null;
  const rawWhen = plain(props['Publish at']).trim();
  if (rawWhen) {
    try { when = parseWhen(rawWhen, s.timezone || 'UTC'); } catch (e) { return problem('The time zone "' + s.timezone + '" in Settings is not valid. Use a name like America/New_York.'); }
    if (!when) return problem('Publish at is not a date Socialync can read.');
  }
  const scheduledAt = new Date(Math.max(earliest, when ? when.getTime() : 0)).toISOString();
  return [{ json: { ok: true, post: {
    profileId: String(s.profileId || '').trim(),
    platforms,
    caption,
    scheduledAt,
    mediaSource: videoUrl ? 'videoUrl' : imageUrl ? 'imageUrls' : 'none',
    imageUrls: imageUrl,
    videoUrl,
    title,
    tiktokPrivacyLevel: level,
    idempotencyKey: safeKey('notion', page.id + ':' + shortHash(rawWhen + '|' + platforms.join(',') + '|' + caption)),
  } } }];
} catch (e) {
  return problem(e.message);
}
